import sys
from flask import Flask
app = Flask(__name__)
calls = []
@app.teardown_appcontext
def t1(exc):
    calls.append('t1'); raise ValueError('a')
@app.teardown_appcontext
def t2(exc):
    calls.append('t2'); raise ValueError('b')
err = None
try:
    with app.app_context():
        pass
except BaseException as e:
    err = e
assert calls == ['t2', 't1']
